  }, [])

  // ticker: snooze expiry, scheduled sends
  useEffect(() => {
    const tick = () => {
      const n = Date.now()
      setNow(n)
      const s = mailRef.current
      const due = s.drafts.filter((d) => d.sendAt && d.sendAt <= n)
      const wake = s.threads.some((t) => t.snoozedUntil && t.snoozedUntil <= n)
      if (!due.length && !wake) return
      let next = s
