[data-theme='dark'] {
  --bg: #1b1c1f; --panel: #26282c; --text: #e3e3e3; --muted: #a0a4a9; --line: #3c4043; --hover: rgba(255,255,255,.1);
  --row-read: #2b2d31; --row-unread: #26282c; --sel: #3f4a5e; --accent: #8ab4f8; --compose: #2e4d7b; --compose-t: #d3e3fd;
  --navsel: #394457; --menu: #2f3136; --shadow: 0 2px 8px 2px rgba(0,0,0,.5); --search: #33363b; --chip: #3c4043; --toast: #4a4d52; --quote: #555;
  color-scheme: dark;
}
* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
body { font-family: 'Google Sans', Roboto, 'Segoe UI', -apple-system, Inter, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--text); font-size: 14px; overflow: hidden; }
button { font: inherit; color: inherit; cursor: pointer; background: none; border: 0; padding: 0; }
button:disabled { opacity: .4; cursor: default; }
a { color: var(--accent); }
input, textarea { font: inherit; color: inherit; }
.ico { flex: none; display: block; }
.grow { flex: 1; }
.muted { color: var(--muted); }

.app { height: 100%; display: flex; flex-direction: column; }
.topbar { height: 64px; display: flex; align-items: center; gap: 4px; padding: 0 12px 0 8px; flex: none; }
.logo { display: flex; align-items: center; gap: 8px; text-decoration: none; color: var(--muted); font-size: 22px; width: 232px; flex: none; white-space: nowrap; }
.logo span { overflow: hidden; text-overflow: ellipsis; }
.ibtn { width: 40px; height: 40px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--muted); flex: none; position: relative; }
.ibtn:hover:not(:disabled), .ibtn.active { background: var(--hover); color: var(--text); }
.ibtn.sm { width: 32px; height: 32px; }
.ibtn.tiny { width: 24px; height: 24px; }
.ibtn.spin .ico { animation: spin .7s linear; }
@keyframes spin { to { transform: rotate(360deg); } }
.avatar { border-radius: 50%; color: #fff; display: inline-flex; align-items: center; justify-content: center; font-weight: 500; flex: none; }
.avatar.sel { background: var(--accent); }
.me-btn { border-radius: 50%; margin-left: 4px; padding: 2px; }

.search { position: relative; flex: 0 1 720px; height: 48px; background: var(--search); border-radius: 24px; display: flex; align-items: center; padding: 0 4px; margin-left: 8px; }
.search.focus { background: var(--panel); box-shadow: var(--shadow); border-radius: 24px 24px 0 0; }
.search input { flex: 1; border: 0; background: none; outline: none; font-size: 16px; min-width: 0; height: 100%; }
.s-panel { position: absolute; top: 48px; left: 0; right: 0; background: var(--panel); box-shadow: var(--shadow); border-radius: 0 0 24px 24px; padding: 8px 0 12px; z-index: 40; max-height: 70vh; overflow: auto; }
.s-chips { display: flex; gap: 8px; flex-wrap: wrap; padding: 4px 16px 10px; }
.s-chips button { border: 1px solid var(--line); border-radius: 8px; padding: 6px 12px; }
.s-chips button:hover { background: var(--hover); }
.s-item { display: flex; align-items: center; gap: 12px; padding: 8px 16px; cursor: pointer; color: var(--muted); }
.s-item:hover { background: var(--hover); }
.s-item > span { flex: 1; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.s-t { display: flex; flex-direction: column; min-width: 0; }
.s-t small { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.s-t b { font-weight: 500; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.body { flex: 1; display: flex; min-height: 0; position: relative; }
.sidebar { width: 256px; flex: none; padding: 8px 0 0 0; overflow-y: auto; transition: width .15s; }
.compose-btn { display: flex; align-items: center; gap: 14px; height: 56px; padding: 0 24px 0 16px; margin: 4px 0 16px 8px; background: var(--compose); color: var(--compose-t); border-radius: 16px; font-weight: 500; font-size: 14px; box-shadow: 0 1px 2px rgba(60,64,67,.3); }
.compose-btn:hover { box-shadow: 0 2px 6px 2px rgba(60,64,67,.2); }
.nav-item { display: flex; align-items: center; gap: 18px; height: 32px; margin-right: 8px; padding: 0 12px 0 26px; border-radius: 0 16px 16px 0; text-decoration: none; color: var(--text); position: relative; }
.nav-item .ico { color: var(--muted); }
.nav-item:hover { background: var(--hover); }
.nav-item.on { background: var(--navsel); font-weight: 700; }
.nav-item.on .ico { color: var(--text); }
.nl { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cnt { font-size: 12px; font-weight: 500; }
.nav-h { display: flex; align-items: center; justify-content: space-between; padding: 16px 12px 4px 26px; font-weight: 500; font-size: 14px; }
.new-label input { margin: 4px 8px 4px 26px; width: calc(100% - 40px); border: 1px solid var(--accent); border-radius: 6px; padding: 6px 8px; background: var(--panel); outline: none; }
.lbl-x { display: none; position: absolute; right: 8px; width: 22px; height: 22px; border-radius: 50%; align-items: center; justify-content: center; color: var(--muted); }
.nav-item:hover .lbl-x { display: inline-flex; }
.nav-item:hover .cnt { display: none; }
.lbl-x:hover { background: var(--hover); }
.collapsed .sidebar { width: 72px; }
.collapsed .compose-btn { padding: 0; width: 56px; justify-content: center; margin-left: 8px; }
.collapsed .compose-btn span, .collapsed .nl, .collapsed .cnt, .collapsed .nav-h span, .collapsed .new-label, .collapsed .lbl-x { display: none !important; }
.collapsed .nav-item { padding-left: 24px; margin-right: 12px; border-radius: 16px; }
.collapsed .nav-h { justify-content: center; padding-left: 12px; }

.panel { flex: 1; min-width: 0; background: var(--panel); border-radius: 16px; margin: 0 16px 16px 0; display: flex; flex-direction: column; overflow: hidden; }
.toolbar { display: flex; align-items: center; gap: 2px; height: 48px; padding: 0 8px 0 10px; border-bottom: 1px solid var(--line); flex: none; }
.toolbar .sep { width: 1px; height: 20px; background: var(--line); margin: 0 6px; }
.selcount { color: var(--muted); margin-right: 12px; font-size: 13px; }
.pager { display: flex; align-items: center; gap: 2px; color: var(--muted); font-size: 12px; }
.pg-t { margin-right: 8px; white-space: nowrap; }
.sel-wrap { display: inline-flex; align-items: center; margin-right: 4px; border-radius: 4px; padding-left: 8px; }
.sel-wrap:hover { background: var(--hover); }
.chk { width: 18px; height: 18px; border: 2px solid var(--muted); border-radius: 2px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; flex: none; }
.chk.on { background: var(--accent); border-color: var(--accent); }
[data-theme='dark'] .chk.on .ico { fill: #1b1c1f; }
.chk.mixed { background: var(--accent); border-color: var(--accent); }
.chk .dash { width: 8px; height: 2px; background: #fff; display: block; }

.tabs { display: flex; border-bottom: 1px solid var(--line); flex: none; overflow-x: auto; }
.tab { display: flex; align-items: center; gap: 14px; padding: 0 16px; height: 48px; min-width: 168px; color: var(--muted); border-bottom: 3px solid transparent; font-weight: 500; white-space: nowrap; }
.tab:hover { background: var(--hover); }
.tab.on { color: var(--tc); border-bottom-color: var(--tc); }
.newb { color: #fff; font-size: 12px; border-radius: 10px; padding: 1px 8px; }
.banner { background: var(--row-read); padding: 10px 16px; border-bottom: 1px solid var(--line); font-size: 13px; }
.banner button { color: var(--accent); margin-left: 10px; font-weight: 500; }
.view-h { padding: 12px 16px 6px; font-size: 18px; font-weight: 500; }
.scroll { flex: 1; overflow-y: auto; min-height: 0; }

.row { display: grid; grid-template-columns: 34px 34px 200px minmax(0, 1fr) 20px 84px; align-items: center; height: 40px; padding: 0 8px 0 12px; border-bottom: 1px solid var(--line); background: var(--row-read); cursor: pointer; position: relative; column-gap: 4px; }
.row.unread { background: var(--row-unread); font-weight: 700; }
.row:hover { box-shadow: inset 1px 0 0 var(--line), inset -1px 0 0 var(--line), 0 1px 3px rgba(60,64,67,.3); z-index: 1; }
.row.selected { background: var(--sel); }
.row.cursor { box-shadow: inset 3px 0 0 var(--accent); }
.d-comfortable .row { height: 52px; }
.d-compact .row { height: 32px; }
.r-avatar { display: none; }
.r-check { display: flex; align-items: center; }
.star { color: var(--muted); display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; opacity: .8; }
.star:hover { opacity: 1; }
.star.on { color: #f4b400; opacity: 1; }
.r-sender, .r-main { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.r-sender { padding-right: 12px; }
.r-subject { color: var(--text); }
.row.read .r-subject { font-weight: 400; }
.r-snip { color: var(--muted); font-weight: 400; }
.r-date { text-align: right; font-size: 12px; white-space: nowrap; }
.row.read .r-date { font-weight: 400; color: var(--muted); }
.row.unread .r-date { color: var(--text); }
.r-att { color: var(--muted); display: flex; }
.sn { display: inline-flex; align-items: center; gap: 3px; color: #b06000; }
.lchip { display: inline-block; color: #fff; font-size: 11px; font-weight: 500; border-radius: 4px; padding: 1px 6px; margin-right: 6px; vertical-align: 1px; }
.lchip.gray { background: var(--muted); }
.r-actions { display: none; position: absolute; right: 8px; top: 50%; transform: translateY(-50%); background: inherit; padding-left: 8px; }
.row:hover .r-actions { display: flex; }
.row:hover .r-date { visibility: hidden; }
.r-actions .ibtn { width: 32px; height: 32px; }
.r-actions .ico { width: 18px; height: 18px; }
mark { background: #ffe58f; color: #202124; border-radius: 2px; }
.draft-t { color: #d93025; font-weight: 400; }
.draftrow .r-sender { font-weight: 400; }
.empty { text-align: center; color: var(--muted); padding: 80px 24px; }
.empty-i { opacity: .35; margin-bottom: 8px; display: flex; justify-content: center; }
.empty h3 { margin: 0 0 6px; color: var(--text); font-weight: 500; font-size: 18px; }
.empty p { margin: 0; }
.foot-note { text-align: center; color: var(--muted); font-size: 12px; padding: 20px; }

.menu { position: absolute; top: 100%; z-index: 60; background: var(--menu); border-radius: 8px; box-shadow: var(--shadow); padding: 6px 0; min-width: 190px; margin-top: 2px; }
.menu.right { right: 0; }
.menu.left { left: 0; }
.dd { position: relative; display: inline-block; }
.dd.up .menu { top: auto; bottom: 100%; margin: 0 0 4px; }
.mitem { display: flex; align-items: center; gap: 12px; width: 100%; padding: 8px 16px; text-align: left; white-space: nowrap; }
.mitem:hover:not(:disabled) { background: var(--hover); }
.mitem .ico { color: var(--muted); }
.mi-t { flex: 1; }
.mi-r { color: var(--muted); font-size: 12px; margin-left: 16px; }
.mi-sp { width: 0; }
.menu-h { padding: 8px 16px; color: var(--muted); font-size: 12px; font-weight: 500; }
.sched { min-width: 280px; }
.pick { display: flex; gap: 8px; padding: 8px 12px; border-top: 1px solid var(--line); margin-top: 4px; }
.pick input { flex: 1; min-width: 0; background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 4px 6px; }
.pick button { color: var(--accent); font-weight: 500; padding: 0 8px; }
.labelmenu { min-width: 240px; }
.lm-in { margin: 0 12px 6px; width: calc(100% - 24px); border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; background: var(--panel); outline: none; }
.lm-in:focus { border-color: var(--accent); }
.settings { width: 300px; padding: 4px 16px 16px; }
.settings .menu-h { padding-left: 0; }
.set-l { margin: 10px 0 4px; font-weight: 500; }
.seg { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.seg button { flex: 1; padding: 6px 4px; text-transform: capitalize; }
.seg button.on { background: var(--navsel); font-weight: 500; }
.settings textarea { width: 100%; border: 1px solid var(--line); border-radius: 6px; padding: 6px; background: var(--panel); resize: vertical; }
.account { width: 300px; padding: 20px; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.account span { color: var(--muted); }
.account b { font-size: 16px; margin-top: 8px; }
.storage { width: 100%; height: 4px; background: var(--chip); border-radius: 2px; margin-top: 14px; }
.storage i { display: block; height: 100%; background: var(--accent); border-radius: 2px; }
.pill { display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 18px; padding: 0 16px; height: 36px; margin-top: 12px; font-weight: 500; }
.pill:hover { background: var(--hover); }

/* thread */
.thread { padding: 8px 24px 40px 24px; max-width: 1000px; }
.t-subject { font-size: 22px; font-weight: 400; margin: 12px 0 16px 56px; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; line-height: 1.3; }
.t-chips { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.tchip { background: var(--chip); border-radius: 4px; font-size: 12px; padding: 2px 4px 2px 8px; display: inline-flex; align-items: center; gap: 4px; }
.tchip:not(:has(button)) { padding-right: 8px; }
.tchip.lbl { color: #fff; cursor: pointer; }
.tchip button { display: inline-flex; opacity: .7; border-radius: 50%; }
.tchip button:hover { opacity: 1; background: rgba(0,0,0,.15); }
.msg { border-bottom: 1px solid var(--line); padding: 14px 0; }
.msg.collapsed { display: flex; align-items: center; gap: 16px; cursor: pointer; color: var(--muted); }
.msg.collapsed:hover { background: var(--hover); }
.msg-sum { flex: 1; min-width: 0; display: flex; gap: 12px; overflow: hidden; white-space: nowrap; }
.msg-sum b { color: var(--text); font-weight: 500; }
.snip { overflow: hidden; text-overflow: ellipsis; }
.msg-date { color: var(--muted); font-size: 12px; white-space: nowrap; }
.msg-date.short { display: none; }
.msg-head { display: flex; align-items: center; gap: 16px; cursor: pointer; }
.msg-who { flex: 1; min-width: 0; }
.msg-from b { font-weight: 500; }
.addr { color: var(--muted); font-size: 12px; }
.to-line { color: var(--muted); font-size: 12px; display: inline-flex; align-items: center; max-width: 100%; }
.to-line:hover { color: var(--text); }
.details { margin: 8px 0 0 56px; display: grid; grid-template-columns: 70px 1fr; gap: 2px 8px; font-size: 12px; color: var(--muted); background: var(--row-read); padding: 10px 14px; border-radius: 8px; }
.details dt { text-align: right; } .details dd { margin: 0; color: var(--text); }
.msg-body { margin: 12px 0 0 56px; line-height: 1.55; font-size: 14px; overflow-wrap: anywhere; }
.msg-body p { margin: 0 0 12px; }
.msg-body blockquote, .c-body blockquote { margin: 8px 0 0 4px; padding-left: 12px; border-left: 2px solid var(--quote); color: var(--muted); }
.msg-body pre { background: var(--row-read); padding: 10px 12px; border-radius: 6px; overflow: auto; font-size: 12.5px; }
.msg-body code { background: var(--row-read); padding: 1px 4px; border-radius: 3px; }
.msg-body table.kv td { padding: 4px 16px 4px 0; vertical-align: top; }
.msg-body table.kv td:first-child { color: var(--muted); }
.btn { display: inline-block; background: var(--accent); color: var(--panel) !important; padding: 8px 18px; border-radius: 18px; text-decoration: none; font-weight: 500; margin-right: 6px; }
.quote-head { color: var(--muted); }
.sig { color: var(--muted); }
.atts { margin: 16px 0 0 56px; }
.atts-h { color: var(--muted); font-size: 12px; margin-bottom: 8px; }
.atts-l { display: flex; gap: 12px; flex-wrap: wrap; }
.att-card { width: 200px; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; cursor: pointer; }
.att-card:hover { box-shadow: 0 1px 4px rgba(60,64,67,.3); }
.att-prev { height: 90px; background: var(--row-read); display: flex; align-items: center; justify-content: center; }
.att-meta { padding: 8px 10px; display: grid; grid-template-columns: auto 1fr; gap: 0 8px; align-items: center; }
.att-k { grid-row: span 2; color: #fff; font-size: 9px; font-weight: 700; padding: 2px 4px; border-radius: 3px; }
.att-n { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; }
.att-meta small { color: var(--muted); }
.actions-row { margin: 18px 0 4px 56px; display: flex; gap: 8px; flex-wrap: wrap; }
.actions-row .pill { margin-top: 0; }
.smart { margin: 8px 0 0 56px; display: flex; gap: 8px; flex-wrap: wrap; }
.smart button { border: 1px solid var(--line); border-radius: 16px; padding: 6px 14px; }
.smart button:hover { background: var(--hover); }
.ibtn.sm .ico { width: 20px; height: 20px; }

/* compose */
.composes { position: fixed; right: 24px; bottom: 0; display: flex; flex-direction: row-reverse; align-items: flex-end; gap: 16px; z-index: 50; pointer-events: none; max-width: calc(100vw - 48px); }
.compose { pointer-events: auto; width: 540px; max-width: 100%; height: 560px; max-height: calc(100vh - 80px); background: var(--panel); border-radius: 10px 10px 0 0; box-shadow: 0 8px 10px 1px rgba(0,0,0,.14), 0 3px 14px 2px rgba(0,0,0,.12), 0 5px 5px -3px rgba(0,0,0,.2); display: flex; flex-direction: column; }
.compose.min { height: auto; width: 260px; }
.compose.max { position: fixed; inset: 5vh 10vw 0 10vw; width: auto; height: auto; max-height: none; max-width: none; border-radius: 10px 10px 0 0; }
.c-head { display: flex; align-items: center; padding: 0 8px 0 16px; height: 40px; background: #404040; color: #fff; border-radius: 10px 10px 0 0; cursor: pointer; flex: none; }
[data-theme='dark'] .c-head { background: #3c4043; }
.c-title { flex: 1; font-weight: 500; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.c-head button { width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; color: #ddd; }
.c-head button:hover { background: rgba(255,255,255,.15); color: #fff; }
.c-fields { flex: none; padding: 0 16px; position: relative; }
.rcpt-row { display: flex; align-items: flex-start; border-bottom: 1px solid var(--line); min-height: 40px; padding: 4px 0; cursor: text; }
.rcpt-label { color: var(--muted); width: 36px; padding-top: 6px; flex: none; }
.rcpt-box { flex: 1; display: flex; flex-wrap: wrap; gap: 4px; position: relative; align-items: center; min-width: 0; }
.rcpt-box input { flex: 1; min-width: 100px; border: 0; outline: 0; background: none; padding: 6px 0; }
.chip { display: inline-flex; align-items: center; gap: 6px; background: var(--chip); border-radius: 14px; padding: 2px 4px 2px 2px; font-size: 13px; max-width: 100%; }
.chip.bad { background: #fce8e6; color: #c5221f; }
.chip button { display: inline-flex; color: var(--muted); border-radius: 50%; }
.chip button:hover { background: var(--hover); }
.ccbcc { position: absolute; right: 16px; top: 10px; display: flex; gap: 8px; }
.ccbcc button { color: var(--muted); }
.ccbcc button:hover { text-decoration: underline; }
.c-subject { width: 100%; border: 0; border-bottom: 1px solid var(--line); outline: 0; background: none; height: 40px; }
.suggest { position: absolute; top: 100%; left: 0; z-index: 70; background: var(--menu); box-shadow: var(--shadow); border-radius: 8px; padding: 6px 0; min-width: 280px; }
.suggest button { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 14px; text-align: left; }
.suggest button.hi, .suggest button:hover { background: var(--hover); }
.suggest span { display: flex; flex-direction: column; }
.suggest small { color: var(--muted); }
.c-body { flex: 1; overflow-y: auto; padding: 12px 16px; outline: 0; line-height: 1.5; min-height: 100px; }
.c-body p { margin: 0; }
.c-atts { display: flex; flex-wrap: wrap; gap: 6px; padding: 6px 16px; }
.att-chip { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--line); border-radius: 16px; padding: 3px 6px 3px 10px; font-size: 12px; }
.att-chip button { display: inline-flex; border-radius: 50%; color: var(--muted); }
.c-foot { display: flex; align-items: center; gap: 8px; padding: 10px 12px; flex: none; }
.send-group { display: flex; }
.send { background: #0b57d0; color: #fff; height: 36px; padding: 0 20px; border-radius: 18px 0 0 18px; font-weight: 500; }
.send:hover { background: #0a4cb8; }
.send-more { background: #0b57d0; height: 36px; width: 32px; border-radius: 0 18px 18px 0; border-left: 1px solid rgba(255,255,255,.4); display: flex; align-items: center; justify-content: center; }
.fmt { display: flex; align-items: center; gap: 0; flex: 1; flex-wrap: wrap; }
.fmt button { width: 32px; height: 32px; border-radius: 4px; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; font-size: 14px; }
.fmt button:hover { background: var(--hover); }
.saved { color: var(--muted); font-size: 12px; }
.disc { width: 36px; height: 36px; border-radius: 4px; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; }
.disc:hover { background: var(--hover); }

.toasts { position: fixed; left: 24px; bottom: 24px; display: flex; flex-direction: column; gap: 8px; z-index: 100; }
.toast { background: var(--toast); color: #fff; border-radius: 6px; padding: 12px 8px 12px 16px; display: flex; align-items: center; gap: 16px; min-width: 300px; box-shadow: var(--shadow); animation: up .2s; }
.toast button { color: #8ab4f8; font-weight: 500; padding: 4px 8px; }
.toast button.tx { color: #ddd; padding: 2px; display: inline-flex; }
.toast span { flex: 1; }
@keyframes up { from { transform: translateY(12px); opacity: 0; } }
.modal-bg { position: fixed; inset: 0; background: rgba(0,0,0,.4); z-index: 200; display: flex; align-items: center; justify-content: center; padding: 16px; }
.modal { background: var(--panel); border-radius: 12px; width: 640px; max-width: 100%; max-height: 90vh; overflow: auto; padding: 8px 24px 24px; }
