  .r-snip { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .r-subject { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .d-comfortable .row, .d-compact .row { height: auto; }
  .thread { padding: 4px 12px 80px; }
  .t-subject { margin-left: 0; font-size: 19px; }
  .msg-body, .atts, .actions-row, .smart, .details { margin-left: 0; }
  .msg-date.full { display: none; } .msg-date.short { display: inline; }
  .tab { min-width: 0; flex: 1; padding: 0 10px; gap: 8px; justify-content: center; } .tab span:not(.newb) { display: none; }
