  .toolbar { padding: 0 4px; overflow-x: auto; }
  .toolbar .pg-t { display: none; }
  .composes { right: 0; left: 0; max-width: none; }
  .compose, .compose.max { position: fixed; inset: 0; width: auto; height: auto; max-height: none; border-radius: 0; pointer-events: auto; }
  .compose.min { inset: auto 0 0 0; width: auto; }
  .c-head { border-radius: 0; }
  .toasts { left: 8px; right: 8px; bottom: 80px; } .toast { min-width: 0; }
  .keys { grid-template-columns: 1fr; }
  .settings, .account { width: min(300px, 90vw); }
}
