.compose { pointer-events: auto; width: 540px; max-width: 100%; height: 560px; max-height: calc(100vh - 80px); background: var(--panel); border-radius: 10px 10px 0 0; box-shadow: 0 8px 10px 1px rgba(0,0,0,.14), 0 3px 14px 2px rgba(0,0,0,.12), 0 5px 5px -3px rgba(0,0,0,.2); display: flex; flex-direction: column; }
