.row.read .r-date { font-weight: 400; color: var(--muted); }
.row.unread .r-date { color: var(--text); }
.r-att { color: var(--muted); display: flex; }
.sn { display: inline-flex; align-items: center; gap: 3px; color: #b06000; }
.lchip { display: inline-block; color: #fff; font-size: 11px; font-weight: 500; border-radius: 4px; padding: 1px 6px; margin-right: 6px; vertical-align: 1px; }
